-- Seed: Indicadores de 5to de Secundaria - Lengua Española

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('5to', 'Lengua Española', 'BC1', 'IL-1', 'Evidencia conocimientos, dominio y habilidades al comunicarse, utilizando un tipo de texto conveniente para relacionarse en diferentes contextos comunicativos, mediante medios y recursos tecnológicos, así como de otros tipos.'),
('5to', 'Lengua Española', 'BC1', 'IL-2', 'Emplea diversidad de textos en situaciones de comunicación para una mayor relación con los demás, usando diferentes medios y recursos tecnológicos y de otros tipos.'),
('5to', 'Lengua Española', 'BC1', 'IL-3', 'Se comunica de manera eficaz, usando diferentes textos, en contextos del ámbito local, nacional y mundial, demostrando criticidad y creatividad de sus ideas.'),

-- BC2
('5to', 'Lengua Española', 'BC2', 'IL-4', 'Demuestra conocimiento y dominio de secuencias argumentativas en discursos diversos, abordando temas sociales y partiendo de sus habilidades de comprensión y producción.'),
('5to', 'Lengua Española', 'BC2', 'IL-5', 'Pone en práctica sus conocimientos de comprensión y producción a partir de explicaciones de temas del entorno familiar, escolar, comunitario, nacional y del mundo, promocionando conocimientos innovadores.'),
('5to', 'Lengua Española', 'BC2', 'IL-6', 'Presenta informaciones en las que sostiene juicios y puntos de vista para la construcción de un pensamiento estructurado, derivando conclusiones y guardando el respeto de las opiniones de los demás.'),
('5to', 'Lengua Española', 'BC2', 'IL-7', 'Utiliza sus conocimientos sobre problemas sociales para búsqueda de posibles soluciones, explicándolas en medios y textos apropiados.'),
('5to', 'Lengua Española', 'BC2', 'IL-8', 'Emplea textos diversos con mayor grado de complejidad y con informaciones confiables, que aportan propuestas para la solución de problemas locales, nacionales e internacionales.'),
('5to', 'Lengua Española', 'BC2', 'IL-9', 'Produce ensayos, informes u otros tipos de textos para presentar conclusiones y recomendaciones de investigaciones realizadas, que plantean soluciones de problemas de diferentes ámbitos.'),

-- BC3
('5to', 'Lengua Española', 'BC3', 'IL-13', 'Realiza investigaciones de acuerdo con su capacidad sobre situaciones que inciden en la comunidad que lo rodea, apoyándose en el uso de una tipología textual conveniente y recursos variados, en demostración de sus habilidades investigativas, lingüísticas, así como del manejo de herramientas tecnológicas.'),
('5to', 'Lengua Española', 'BC3', 'IL-14', 'Produce textos variados, especialmente de secuencia expositivo-explicativa, para presentar resultados de investigaciones sobre temas sociales de diferentes ámbitos, evidenciando uso adecuado de la lengua y manejo de herramientas tecnológicas y otros recursos.'),
('5to', 'Lengua Española', 'BC3', 'IL-15', 'Publica resultados de investigaciones realizadas, de incidencia escolar, comunitario y nacional, apoyándose en medios y recursos tecnológicos y haciendo uso de un género textual conveniente, evidenciando niveles de comprensión y producción, así como conocimiento sobre estudios científicos.'),
('5to', 'Lengua Española', 'BC3', 'IL-16', 'Identifica, con mayor nivel de criticidad, temas diversos sobre salud, ambiente, alimentación, entre otros que inciden positiva o negativamente en la comunidad, a través de textos apropiados y el apoyo de herramientas tecnológicas, derivando en propuestas de solución.'),
('5to', 'Lengua Española', 'BC3', 'IL-17', 'Elabora diversidad de textos como catálogos, recetas, artículos de opinión, instructivos, con la finalidad de dar a conocer y promover temáticas relacionadas con la salubridad, el medioambiente, la alimentación, proponiendo alternativas de solución o mejora.'),
('5to', 'Lengua Española', 'BC3', 'IL-18', 'Utiliza variedad de textos (funcionales y literarios) en actividades de intercomunicación, para sensibilizar los seres humanos sobre la exhibición de un buen comportamiento y realización de acciones positivas frente a situaciones y temas relacionados con preservación de la salud, cuidado de los recursos naturales y sus ecosistemas.'),

-- BC4
('5to', 'Lengua Española', 'BC4', 'IL-10', 'Especifica nuevas relaciones socioculturales en las diferentes situaciones de comunicación que participa, caracterizándolas mediante un género textual.'),
('5to', 'Lengua Española', 'BC4', 'IL-11', 'Produce textos diversos para la promoción de prácticas sociales de ciudadanía y valores universales, en variados contextos, como aporte al fortaleciendo de las relaciones de los seres humanos.'),
('5to', 'Lengua Española', 'BC4', 'IL-12', 'Elabora proyectos que valoran las prácticas ciudadanas de la comunidad, así como la solución a los problemas, haciendo uso de textos adecuados.'),
('5to', 'Lengua Española', 'BC4', 'IL-19', 'Evidencia compromisos más profundos consigo mismo, así como con los demás, a través de textos convenientes, fortaleciendo los niveles de confianza y comprensión ante el comportamiento de la humanidad.'),
('5to', 'Lengua Española', 'BC4', 'IL-20', 'Cultiva valores universales y refuerza la dimensión humanista mediante textos relacionados que produce, para el fortalecimiento de su persona y apoyo a los demás.'),
('5to', 'Lengua Española', 'BC4', 'IL-21', 'Reflexiona, mediante textos diversos (orales y escritos), en procura de canalizar emociones y sentimientos, así como fortalecer valores espirituales, como claves para el respeto a la dignidad y las buenas relaciones de las personas.');
